from collections import defaultdict
# Thompson yapimi (regex -> eps-NFA) ve alt kume yapimi (eps-NFA -> DFA)
# Regex'te birlestirme acikca '.' ile yazilir.
trans = defaultdict(set)   # (durum, sembol|None) -> {durum}
sayac = [0]

def yeni():
    sayac[0] += 1
    return sayac[0] - 1

def birlestir(tut, at):          # iki durumu tek duruma indirger
    global trans
    yt = defaultdict(set)
    f = lambda q: tut if q == at else q
    for (a, s), bs in trans.items():
        yt[(f(a), s)] |= {f(b) for b in bs}
    trans = yt

def postfix(rx):
    onc = {'|': 1, '.': 2, '*': 3}
    cik, yig = [], []
    for c in rx:
        if c == '(':
            yig.append(c)
        elif c == ')':
            while yig[-1] != '(':
                cik.append(yig.pop())
            yig.pop()
        elif c in onc:
            while yig and yig[-1] != '(' and onc.get(yig[-1], 0) >= onc[c]:
                cik.append(yig.pop())
            yig.append(c)
        else:
            cik.append(c)
    return cik + yig[::-1]

def thompson(rx):
    yig = []
    atilan = 0
    for c in postfix(rx):
        if c == '.':
            (s2, a2), (s1, a1) = yig.pop(), yig.pop()
            birlestir(a1, s2); atilan += 1
            yig.append((s1, a1 if a2 == s2 else a2))
        elif c == '|':
            (s2, a2), (s1, a1) = yig.pop(), yig.pop()
            s, a = yeni(), yeni()
            trans[(s, None)] |= {s1, s2}
            trans[(a1, None)].add(a); trans[(a2, None)].add(a)
            yig.append((s, a))
        elif c == '*':
            s1, a1 = yig.pop()
            s, a = yeni(), yeni()
            trans[(s, None)] |= {s1, a}
            trans[(a1, None)] |= {s1, a}
            yig.append((s, a))
        else:
            s, a = yeni(), yeni()
            trans[(s, c)].add(a)
            yig.append((s, a))
    return yig.pop(), sayac[0] - atilan

def kapanis(S):
    yig, gor = list(S), set(S)
    while yig:
        q = yig.pop()
        for r in trans.get((q, None), ()):
            if r not in gor:
                gor.add(r); yig.append(r)
    return frozenset(gor)

