# Dogrudan sol ozyineleme giderme + sol carpanlama (elle izlenebilir gramerler)
def sol_ozyineleme_gider(A, kurallar):
    """A -> A a1 | ... | b1 | ...  =>  A -> b1 A' ... ,  A' -> a1 A' ... | eps"""
    ozyine = [k[1:] for k in kurallar if k and k[0] == A]
    duz = [k for k in kurallar if not (k and k[0] == A)]
    if not ozyine:
        return {A: kurallar}, 0
    Ay = A + "'"
    yeni = {A: [k + [Ay] for k in duz],
            Ay: [k + [Ay] for k in ozyine] + [["eps"]]}
    return yeni, 1

