def sol_carpanla(A, kurallar):
    """En uzun ortak on eki bul, varsa carpanla."""
    en_iyi, en_uzun = None, 0
    for k1 in kurallar:
        for k2 in kurallar:
            if k1 is k2:
                continue
            n = 0
            while n < min(len(k1), len(k2)) and k1[n] == k2[n]:
                n += 1
            if n > en_uzun:
                en_uzun, en_iyi = n, k1[:n]
    if not en_iyi:
        return {A: kurallar}, 0
    uyan = [k for k in kurallar if k[:en_uzun] == en_iyi]
    digerleri = [k for k in kurallar if k[:en_uzun] != en_iyi]
    Ay = A + "'"
    return {A: [en_iyi + [Ay]] + digerleri,
            Ay: [k[en_uzun:] or ["eps"] for k in uyan]}, 1


