import re

def tara(s):
    return re.findall(r"\d+|[-+*/()]", s)

class P:                       # ozyinelemeli inis; hem somut hem soyut agac uretir
    def __init__(self, tok):
        self.t = tok; self.i = 0
    def bak(self):
        return self.t[self.i] if self.i < len(self.t) else None
    def ye(self, x=None):
        v = self.t[self.i]; self.i += 1; return v
    def E(self):
        somut, soyut = ["E"], None
        a_s, a_a = self.T()
        somut = ["E", a_s]; soyut = a_a
        while self.bak() == "+":
            op = self.ye()
            b_s, b_a = self.T()
            somut = ["E", somut, op, b_s]
            soyut = ("+", soyut, b_a)
        return somut, soyut
    def T(self):
        a_s, a_a = self.F()
        somut = ["T", a_s]; soyut = a_a
        while self.bak() == "*":
            op = self.ye()
            b_s, b_a = self.F()
            somut = ["T", somut, op, b_s]
            soyut = ("*", soyut, b_a)
        return somut, soyut
    def F(self):
        if self.bak() == "(":
            self.ye()
            e_s, e_a = self.E()
            self.ye()
            return ["F", "(", e_s, ")"], e_a
        n = self.ye()
        return ["F", n], ("num", int(n))

def say_somut(d):
    if isinstance(d, str):
        return 1
    return 1 + sum(say_somut(c) for c in d[1:])

def say_soyut(d):
    if d[0] == "num":
        return 1
    return 1 + say_soyut(d[1]) + say_soyut(d[2])

def yaz(d):
    if d[0] == "num":
        return str(d[1])
    return "(%s %s %s)" % (d[0], yaz(d[1]), yaz(d[2]))

def deger(d):
    if d[0] == "num":
        return d[1]
    a, b = deger(d[1]), deger(d[2])
    return a + b if d[0] == "+" else a * b

for s in ["3 + 4 * 5", "(3 + 4) * 5", "1 + 2 + 3"]:
    p = P(tara(s))
    somut, soyut = p.E()
    print("%-12s somut dugum=%2d  AST dugum=%d  AST=%-17s deger=%d"
          % (s, say_somut(somut), say_soyut(soyut), yaz(soyut), deger(soyut)))

