from collections import defaultdict
# Veri akisi analizi: erisen tanimlar (reaching definitions) + canli degiskenler
# CFG:
#   B1: d1: i = 0
#   B2: if i < n goto B4   (cikis: B3)
#   B3: goto CIKIS
#   B4: d2: t = n * 8 ; d3: s = s + t ; d4: i = i + 1 ; goto B2
BLOK = {
    "B1": [("d1", "i", ["0"])],
    "B2": [],
    "B3": [],
    "B4": [("d2", "t", ["n"]), ("d3", "s", ["s", "t"]), ("d4", "i", ["i"])],
}
ARDIL = {"B1": ["B2"], "B2": ["B3", "B4"], "B3": [], "B4": ["B2"]}
ONCUL = defaultdict(list)
for b, ss in ARDIL.items():
    for s in ss:
        ONCUL[s].append(b)
B2_KULLANIM = {"i", "n"}

TUM = [d for b in BLOK for d, _, _ in BLOK[b]]
TANIM = {d: v for b in BLOK for d, v, _ in BLOK[b]}
print("tanim sayisi:", len(TUM), TUM)

# gen / kill
gen, kill = {}, {}
for b in BLOK:
    g, k = set(), set()
    for d, v, _ in BLOK[b]:
        g -= {x for x in g if TANIM[x] == v}
        g.add(d)
        k |= {x for x in TUM if TANIM[x] == v and x != d}
    gen[b], kill[b] = g, k
    print("%s: gen=%s kill=%s" % (b, sorted(g), sorted(k)))

# Erisen tanimlar: ileri yonlu, birlesim (union)
GIRIS = {b: set() for b in BLOK}
CIKIS = {b: set(gen[b]) for b in BLOK}
tur = 0
while True:
    tur += 1
    degisti = False
    for b in ["B1", "B2", "B3", "B4"]:
        yeni_giris = set()
        for p in ONCUL[b]:
            yeni_giris |= CIKIS[p]
        yeni_cikis = gen[b] | (yeni_giris - kill[b])
        if yeni_giris != GIRIS[b] or yeni_cikis != CIKIS[b]:
            GIRIS[b], CIKIS[b] = yeni_giris, yeni_cikis
            degisti = True
    if not degisti:
        break
print("yineleme turu:", tur)
for b in ["B1", "B2", "B3", "B4"]:
    print("%s: GIRIS=%s  CIKIS=%s" % (b, sorted(GIRIS[b]), sorted(CIKIS[b])))
print("B4 girisine erisen tanim sayisi:", len(GIRIS["B4"]))

# Canli degiskenler: geri yonlu, birlesim
KULLANIM = {"B1": set(), "B2": set(B2_KULLANIM), "B3": set(),
            "B4": {"n", "s", "i"}}
TANIMLANAN = {"B1": {"i"}, "B2": set(), "B3": set(), "B4": {"t", "s", "i"}}
CANLI_GIRIS = {b: set() for b in BLOK}
CANLI_CIKIS = {b: set() for b in BLOK}
tur2 = 0
while True:
    tur2 += 1
    degisti = False
    for b in ["B4", "B3", "B2", "B1"]:
        yc = set()
        for s in ARDIL[b]:
            yc |= CANLI_GIRIS[s]
        yg = KULLANIM[b] | (yc - TANIMLANAN[b])
        if yc != CANLI_CIKIS[b] or yg != CANLI_GIRIS[b]:
            CANLI_CIKIS[b], CANLI_GIRIS[b] = yc, yg
            degisti = True
    if not degisti:
        break
print()
print("canli degisken yineleme turu:", tur2)
for b in ["B1", "B2", "B3", "B4"]:
    print("%s: canli-giris=%s canli-cikis=%s"
          % (b, sorted(CANLI_GIRIS[b]), sorted(CANLI_CIKIS[b])))

